object mensajeria {
  var empleados = []
  var paquetesPendientes = []

  method empleados() {
    return empleados
  }

  method contratar(unaPersona) {
    empleados.add(unaPersona)
  }

  method despedir(unEmpleado) {
    empleados.remove(unEmpleado)
  }

  method despedirATodos() {
    empleados = []
  }

  method esGrande() {
    return empleados.size() > 2
  }

  method loEntregaElPrimero() {
    return paquete.puedeSerEntregadoPor( empleados.head() )
  }

  method pesoDelUltimo() {
    return empleados.last().peso()
  }

  method algunoPuedeEntregar(unPaquete) {
    return empleados.any({unEmpleado => unPaquete.puedeSerEntregadoPor(unEmpleado)})
  }

  method candidatosPara(unPaquete) {
    return empleados.filter({unEmpleado => unPaquete.puedeSerEntregadoPor(unEmpleado)})
  }

  method tieneSobrepeso() {
    return empleados.sum({unEmpleado => unEmpleado.peso()}) / empleados.size() > 500
  }

  method enviar(unPaquete) {
    if(empleados.any({unEmpleado => unPaquete.puedeSerEntregadoPor(unEmpleado)})) {
      paquetesPendientes.remove(unPaquete)
    }
    else if(not paquetesPendientes.any({otroPaquete => unPaquete === otroPaquete})){
      paquetesPendientes.add(unPaquete)
    }
  }

  method enviarTodos(unosPaquetes) {
    unosPaquetes.forEach({unPaquete => self.enviar(unPaquete)})
  }

  method enviarPendienteCaro() {
    self.enviar(self.paqueteMasCaro(paquetesPendientes))
  }

  method paqueteMasCaro(unosPaquetes) {
    return unosPaquetes.find({unPaquete => unosPaquetes.all({otroPaquete => unPaquete.precio() >= otroPaquete.precio()}) })
  }

  method pendientes() {
    return paquetesPendientes
  }

  method pendientes(unosPaquetes) {
    paquetesPendientes = unosPaquetes
  }
}


